import{z as s,x as B,o as r,c as d,q as A,j as l,D as n,d as E,s as o,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"指数调整事件","description":"","frontmatter":{"title":"指数调整事件","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/ed-index-rebalance-event.md","filePath":"quant/ed-index-rebalance-event.md","lastUpdated":1791063341000}'),p={name:"quant/ed-index-rebalance-event.md"};function u(m,a,F,h,c,f){const t=B("Mermaid");return r(),d("div",null,[a[2]||(a[2]=A('<h1 id="指数调整事件" tabindex="-1">指数调整事件 <a class="header-anchor" href="#指数调整事件" aria-label="Permalink to &quot;指数调整事件&quot;">​</a></h1><div class="epigraph"><p>被纳入指数的公司在宣布日上涨，尽管公司没有发生任何基本面变化；价格响应的是需求，不是消息。</p><footer>—— 据 Shleifer, Journal of Finance, 1986；Harris and Gurel, Journal of Finance, 1986 整理</footer></div><p><a href="/quant/ed-earnings-event">上一课</a>把财报收成五元组：时点可知，载荷未知。本课挪到事件谱系的另一端：指数调整的时点与数量都由公开规则事先决定，载荷几乎没有新信息——它交易的是<strong>规则决定的机械资金流</strong>。策略经济学的完整展开在<a href="/quant/index-rebalance-arb">指数调仓套利</a>里已经写透；本课在事件化框架里写它与其他日程事件的分工：谁在何时必须成交多少，风控在哪里换挡。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>指数调整事件的定义有三层。第一，<strong>时点由规则日历给出</strong>：定期审核（罗素重组、标普季度审核、MSCI 半年调整）的宣布日与生效日提前公开，无需预测「公司会不会公告」。第二，<strong>数量可事先推算</strong>：调入调出名单可由编制规则在当时证明，权重变动 \\(\\Delta w\\) 乘以跟踪产品的资产规模，就是被动资金必须成交的量。第三，<strong>载荷近似为零</strong>：被调入不是好消息——它是其他投资者将要被迫买入的好消息。放回五元组：\\(T\\) 有宣布与生效两个；\\(X\\) 是名单与权重变动；\\(E\\) 是事前可推算的预期名单，抢跑由此而来；\\(W\\) 是宣布到生效的窗口；\\(F\\) 是 \\(\\Delta w\\) 对应的机械流量。缺口在于：流量在时间线上如何分布，谁能提前承接、谁必须在生效日吃进。</p><p><span class="marginnote">直觉类比：被调入指数就像被选为全班必须买的教学范本——公司本身没变好，变的是「有一群人不管价格多高都得买你」。宣布日涨的是这条强制需求，不是基本面；把上涨读成「好消息」就找错了因果。</span></p><h3 id="双时点结构" tabindex="-1">双时点结构 <a class="header-anchor" href="#双时点结构" aria-label="Permalink to &quot;双时点结构&quot;">​</a></h3><p>财报是单时点事件，指数调整天然是双时点：宣布日 \\(\\tau_a\\)，规则生效日 \\(\\tau_e\\)，\\(\\tau_a\\lt\\tau_e\\)。宣布效应在 \\(\\tau_a\\) 后开始吸收预期；生效日的集中成交（常压进收盘拍卖，<a href="/quant/close-auction-imbalance">收盘竞价不平衡</a>的机制在调仓日被放大）打进实际冲击。两个窗口承载两种不同的交易：前者交易预期修正，后者承接流动性。把它们混成一个「调仓效应」，回测会同时高估两者。</p><p><span class="marginnote">Harris 与 Gurel（1986）：宣布日样本平均抬升约 3%、成交量放大近一倍，而公司价值不变——需求移动而非信息。拿旧效应当现值是这一行最常见的错误。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>名单在宣布前推算，只用当时可知的信息。</strong> 编制规则给出市值、流动性、行业配额的门槛，按生效日前数据可证明的候选名单就是 \\(E\\)。事后名单做研究可以，做信号不行——<a href="/quant/index-rebalance-arb">指数调仓套利</a>反复强调的口径。</p><p><strong>流量按产品分解。</strong> \\(F\\approx\\sum_f (w^{\\mathrm{new}}_f-w^{\\mathrm{old}}_f)\\cdot \\mathrm{AUM}_f\\)，再除以日均成交额定冲击量级。被动基金、ETF（<a href="/quant/cn-etf-creation">ETF 申赎</a>）、杠杆与增强产品的执行风格不同：有的钉收盘，有的分段。流量分解到执行风格，才能预测生效日拍卖的真实压力。</p><p><span class="marginnote">数字实例：某股新增权重 0.2%，跟踪指数的被动资产共 10 万亿美元，机械买盘约 0.2% × 10 万亿 = 200 亿美元；若该股日均成交额 20 亿美元，相当于 10 个交易日的成交量——而其中大头还压进生效日收盘拍卖的几分钟里。</span></p><p><strong>窗口分账。</strong> 宣布窗测预期吸收，生效窗测流动性冲击，生效后窗测回吐与留存。三段账分开记，效应衰减与拥挤才有观测点。</p>',14)),(r(),l(i,null,{default:n(()=>[o(t,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20RULE%5B%22%E7%BC%96%E5%88%B6%E8%A7%84%E5%88%99%E4%B8%8E%E5%AE%A1%E6%A0%B8%E6%97%A5%E5%8E%86%22%5D%20--%3E%20LIST%5B%22%E5%8F%AF%E8%AF%81%E6%98%8E%E5%90%8D%E5%8D%95%E4%B8%8E%20Delta%20w%22%5D%0A%20%20LIST%20--%3E%20ANN%5B%22%E5%AE%A3%E5%B8%83%E6%97%A5%EF%BC%9A%E9%A2%84%E6%9C%9F%E5%90%B8%E6%94%B6%20%E6%8A%A2%E8%B7%91%22%5D%0A%20%20ANN%20--%3E%20EFF%5B%22%E7%94%9F%E6%95%88%E6%97%A5%EF%BC%9A%E8%A2%AB%E5%8A%A8%E6%B5%81%E9%87%8F%E9%9B%86%E4%B8%AD%E6%88%90%E4%BA%A4%22%5D%0A%20%20EFF%20--%3E%20AUCTION%5B%22%E6%94%B6%E7%9B%98%E6%8B%8D%E5%8D%96%E6%89%BF%E6%8E%A5%E5%86%B2%E5%87%BB%22%5D%0A%20%20AUCTION%20--%3E%20POST%5B%22%E7%94%9F%E6%95%88%E5%90%8E%EF%BC%9A%E4%B8%B4%E6%97%B6%E5%86%B2%E5%87%BB%E5%9B%9E%E5%90%90%20%E6%B0%B8%E4%B9%85%E9%83%A8%E5%88%86%E7%95%99%E5%AD%98%22%5D%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("价格机制是"),e("strong",null,"向下倾斜的需求曲线"),E("：被动资金对价格不敏感，它的到达制造暂时性价格压力；灵活资本承接压力要求补偿。临时部分在生效后回吐，永久部分对应指数产品将长期持有的权重——两类效应用同一个哑变量去估，就把回吐与留存搅成了噪声。拥挤机制决定效应的斜率：日历公开使策略可复制，复制不需要模型只需要日历；资本涌入后宣布效应被提前吸收，生效日冲击变浅，一旦流量异常放大，承接资本的同步减仓会把冲击放大回来。")],-1)),a[5]||(a[5]=e("p",null,"风控换挡点在时间线上：宣布窗的主要风险是「预期名单错了」（细则、快速进出与豁免），生效窗的主要风险是执行（借券可得性、涨跌停与流动性）——两窗的止损逻辑不同，不能共用一条线。",-1)),(r(),l(i,null,{default:n(()=>[o(t,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20SUB%5B%22%E5%8F%8C%E6%97%B6%E7%82%B9%E4%BA%8B%E4%BB%B6%22%5D%20--%3E%20ANN%5B%22%E5%AE%A3%E5%B8%83%E7%AA%97%22%5D%0A%20%20SUB%20--%3E%20EFF%5B%22%E7%94%9F%E6%95%88%E7%AA%97%22%5D%0A%20%20ANN%20--%3E%20A1%5B%22%E4%BA%A4%E6%98%93%E7%9A%84%E6%98%AF%3A%20%E9%A2%84%E6%9C%9F%E4%BF%AE%E6%AD%A3%22%5D%0A%20%20ANN%20--%3E%20A2%5B%22%E9%A3%8E%E9%99%A9%3A%20%E9%A2%84%E6%9C%9F%E5%90%8D%E5%8D%95%E9%94%99%E5%88%A4%20%E7%BB%86%E5%88%99%E4%B8%8E%E8%B1%81%E5%85%8D%22%5D%0A%20%20ANN%20--%3E%20A3%5B%22%E6%AD%A2%E6%8D%9F%E7%9C%8B%3A%20%E8%A7%84%E5%88%99%E6%96%87%E6%9C%AC%E4%B8%8E%E5%90%8D%E5%8D%95%E8%AF%81%E6%8D%AE%22%5D%0A%20%20EFF%20--%3E%20E1%5B%22%E6%89%BF%E6%8E%A5%E7%9A%84%E6%98%AF%3A%20%E6%9C%BA%E6%A2%B0%E6%B5%81%E9%87%8F%22%5D%0A%20%20EFF%20--%3E%20E2%5B%22%E9%A3%8E%E9%99%A9%3A%20%E6%89%A7%E8%A1%8C%20%E5%80%9F%E5%88%B8%20%E6%B6%A8%E8%B7%8C%E5%81%9C%20%E6%B5%81%E5%8A%A8%E6%80%A7%22%5D%0A%20%20EFF%20--%3E%20E3%5B%22%E6%AD%A2%E6%8D%9F%E7%9C%8B%3A%20%E6%88%90%E4%BA%A4%E4%B8%8E%E5%86%B2%E5%87%BB%E6%88%90%E6%9C%AC%22%5D%0A"})]),fallback:n(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=A('<p><span class="marginnote">常见误区：用生效日一天的异常收益代表「指数效应」。临时冲击会在生效后回吐，永久部分才留存；两者混进同一个哑变量，估出的数既不是回吐前的高点、也不是留存后的水平，而是一团解释不了的噪声。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重写调仓套利的容量与执行细节，那是<a href="/quant/index-rebalance-arb">指数调仓套利</a>的对象；也不写对未公开名单的刺探——公开规则下的推算是研究，非公开信息是另一套信息集。权重的被动漂移（不调样也发生的权重变动）是连续流量，不是事件，混进事件表会稀释日历效应。同日多指数生效叠加时，事件不再是独立样本，要按组合处理。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指数调整是规则决定的双时点事件：宣布日吸收预期，生效日承接机械流量，两窗分账。</li><li>名单可由公开规则事先证明，流量可由规则与产品规模推算；事后名单不能当信号。</li><li>价格响应是需求移动不是信息：临时冲击回吐，永久部分留存，不可共用一个哑变量。</li><li>拥挤使效应衰减；日历公开性让复制不需要模型，溢价随资本周期起伏。</li><li>出处：Shleifer, <em>Journal of Finance</em>, 1986；Harris and Gurel, <em>Journal of Finance</em>, 1986；Chen, Noronha and Singal, <em>Journal of Finance</em>, 2004；Madhavan, <em>Financial Analysts Journal</em>, 2003。</li></ul>',5))])}const b=s(p,[["render",u]]);export{_ as __pageData,b as default};
